Quantum GetPixelChannel(const Image *image, const PixelChannel channel, const Quantum *pixel) {
  if (!image || !pixel) {
    return 0;
  }

  if (channel >= MaxPixelChannels) {
    return 0;
  }

  if (image->channel_info[channel].traits == UndefinedChannel) {
    return 0;
  }

  return pixel[channel];
}
